{"content": "import Foundation
import AppKit
import Vision

// 1) OCR（带归一化坐标，原点左下）—— 我只想读出工具栏上的文字，定位不了"圈了哪两个"
let path = CommandLine.arguments[1]
guard let img = NSImage(contentsOfFile: path),
      let cg = img.cgImage(forProposedRect: nil, context: nil, hints: nil) else {
    print("FAIL load"); exit(1)
}
print("SIZE \(cg.width)x\(cg.height)")

let req = VNRecognizeTextRequest()
req.recognitionLevel = .accurate
req.recognitionLanguages = ["zh-Hans", "en-US"]
try VNImageRequestHandler(cgImage: cg, options: [:]).perform([req])
for obs in (req.results ?? []) {
    guard let c = obs.topCandidates(1).first else { continue }
    let b = obs.boundingBox
    let x = b.minX * Double(cg.width)
    let yTop = (1 - b.maxY) * Double(cg.height)
    let w = b.width * Double(cg.width)
    let h = b.height * Double(cg.height)
    print(String(format: "BOX %6.0f %6.0f %6.0f %6.0f  %@", x, yTop, w, h, c.string))
}

// 2) 找"批注色"（纯红系）像素团 —— 宿主圈的记号一般就是这个色，UI 里没有这种红
guard let rep = NSBitmapImageRep(cgImage: cg) as NSBitmapImageRep? else { exit(1) }
var pts: [(Int, Int)] = []
let W = rep.pixelsWide, H = rep.pixelsHigh
let step = max(1, W / 900)
for y in stride(from: 0, to: H, by: step) {
    for x in stride(from: 0, to: W, by: step) {
        guard let c = rep.colorAt(x: x, y: y) else { continue }
        let r = c.redComponent, g = c.greenComponent, b = c.blueComponent
        if r > 0.5 && r - max(g, b) > 0.22 { pts.append((x, y)) }
    }
}
print("REDPX \(pts.count) (sampled every \(step)px)")
if !pts.isEmpty {
    // 简单聚类：按 x/y 距离 > 40 切断
    var clusters: [[(Int, Int)]] = []
    for p in pts {
        var placed = false
        for i in clusters.indices {
            if clusters[i].contains(where: { abs($0.0 - p.0) < 60 && abs($0.1 - p.1) < 60 }) {
                clusters[i].append(p); placed = true; break
            }
        }
        if !placed { clusters.append([p]) }
    }
    for (i, cl) in clusters.enumerated() where cl.count > 8 {
        let xs = cl.map { $0.0 }, ys = cl.map { $0.1 }
        let x0 = xs.min()!, x1 = xs.max()!, y0 = ys.min()!, y1 = ys.max()!
        print("CLUSTER#\(i) n=\(cl.count) x=\(x0)..\(x1) y=\(y0)..\(y1)")
    }
}
