{"content": "import Foundation
import AppKit

// 把"批注色"像素画成 ASCII 图（每格 8x8 px），看宿主到底圈了什么形状
let path = CommandLine.arguments[1]
guard let img = NSImage(contentsOfFile: path),
      let cg = img.cgImage(forProposedRect: nil, context: nil, hints: nil),
      let rep = NSBitmapImageRep(cgImage: cg) else { print("FAIL"); exit(1) }
let W = rep.pixelsWide, H = rep.pixelsHigh
let cell = Int(CommandLine.arguments.count > 2 ? Int(CommandLine.arguments[2])! : 8)
print("SIZE \(W)x\(H) cell=\(cell)")
var grid = [[Bool]](repeating: [Bool](repeating: false, count: W / cell + 1), count: H / cell + 1)
var total = 0
for y in 0..<H {
    for x in 0..<W {
        guard let c = rep.colorAt(x: x, y: y) else { continue }
        let r = c.redComponent, g = c.greenComponent, b = c.blueComponent
        if r > 0.45 && r - max(g, b) > 0.18 {
            grid[y / cell][x / cell] = true
            total += 1
        }
    }
}
print("RED \(total)")
for row in 0..<grid.count {
    var line = String(format: "%4d ", row * cell)
    for col in 0..<grid[row].count { line += grid[row][col] ? "#" : "." }
    print(line)
}
