{"content": "import Foundation
import AppKit

// 区域体检：暗像素（文字）ASCII 图 + 饱和色统计（笔色圆点）
let path = CommandLine.arguments[1]
let x0 = Int(CommandLine.arguments[2])!, y0 = Int(CommandLine.arguments[3])!
let w = Int(CommandLine.arguments[4])!, h = Int(CommandLine.arguments[5])!

guard let img = NSImage(contentsOfFile: path),
      let cg = img.cgImage(forProposedRect: nil, context: nil, hints: nil) else { print("FAIL"); exit(1) }
let rep = NSBitmapImageRep(cgImage: cg)
let cell = 4
print("REGION \(x0),\(y0) \(w)x\(h)")
print("— 暗像素图（文字是 #；每格 \(cell)px）—")
for gy in stride(from: y0, to: y0 + h, by: cell) {
    var line = String(format: "%4d ", gy)
    for gx in stride(from: x0, to: x0 + w, by: cell) {
        var dark = false
        for dy in 0..<cell { for dx in 0..<cell {
            guard let c = rep.colorAt(x: gx + dx, y: gy + dy) else { continue }
            if c.brightnessComponent < 0.45 { dark = true }
        } }
        line += dark ? "#" : "."
    }
    print(line)
}
print("— 饱和色（可能是笔色圆点）—")
var hist: [String: Int] = [:]
for y in y0..<(y0 + h) { for x in x0..<(x0 + w) {
    guard let c = rep.colorAt(x: x, y: y) else { continue }
    let mx = max(c.redComponent, c.greenComponent, c.blueComponent)
    let mn = min(c.redComponent, c.greenComponent, c.blueComponent)
    if mx > 0.35 && (mx - mn) > 0.12 {
        let key = String(format: "r%.2f g%.2f b%.2f", c.redComponent, c.greenComponent, c.blueComponent)
        hist[key, default: 0] += 1
    }
} }
for (k, v) in hist.sorted(by: { $0.value > $1.value }).prefix(12) { print("  \(v)  \(k)") }
