let path = CommandLine.arguments[1]
let x0 = Int(CommandLine.arguments[2])!, x1 = Int(CommandLine.arguments[3])!
let y0 = Int(CommandLine.arguments[4])!, y1 = Int(CommandLine.arguments[5])!
let cell = Int(CommandLine.arguments[6]) ?? 4

guard let img = NSImage(contentsOfFile: path),
      let cg = img.cgImage(forProposedRect: nil, context: nil, hints: nil) else { print("FAIL"); exit(1) }
let rep = NSBitmapImageRep(cgImage: cg)

// header ruler
var ruler = "     "
var i = x0
while i < x1 { ruler += (i % 100 == 0) ? "|" : (i % 20 == 0 ? "'" : " "); i += cell }
print(ruler)

for gy in stride(from: y0, to: y1, by: cell) {
    var line = String(format: "%4d ", gy)
    for gx in stride(from: x0, to: x1, by: cell) {
        var dark = 0, red = 0
        for dy in 0..<cell { for dx in 0..<cell {
            guard let c = rep.colorAt(x: gx + dx, y: gy + dy) else { continue }
            if c.brightnessComponent < 0.5 { dark += 1 }
            if c.redComponent > 0.80 && c.greenComponent < 0.45 && c.blueComponent < 0.45 { red += 1 }
        } }
        if red > 0 { line += "R" } else if dark > (cell*cell)/8 { line += "#" } else if dark > 0 { line += "." } else { line += " " }
    }
    print(line)
}
