import Foundation
import AppKit
import Vision

// 裁一段区域再 OCR —— 用来看"红框里到底是什么"
let path = CommandLine.arguments[1]
let x0 = Int(CommandLine.arguments[2])!, y0 = Int(CommandLine.arguments[3])!
let w = Int(CommandLine.arguments[4])!, h = Int(CommandLine.arguments[5])!

guard let img = NSImage(contentsOfFile: path),
      let cg = img.cgImage(forProposedRect: nil, context: nil, hints: nil) else { print("FAIL"); exit(1) }
guard let crop = cg.cropping(to: CGRect(x: x0, y: y0, width: w, height: h)) else { print("CROP FAIL"); exit(1) }

// 放大 3 倍再 OCR（小字 + 12px 高，直接识别率低）
let scale = 3
let sw = crop.width * scale, sh = crop.height * scale
let cs = CGColorSpaceCreateDeviceRGB()
guard let ctx = CGContext(data: nil, width: sw, height: sh, bitsPerComponent: 8, bytesPerRow: 0,
                          space: cs, bitmapInfo: CGImageAlphaInfo.premultipliedLast.rawValue) else { exit(1) }
ctx.interpolationQuality = .high
ctx.draw(crop, in: CGRect(x: 0, y: 0, width: sw, height: sh))
guard let big = ctx.makeImage() else { exit(1) }

let req = VNRecognizeTextRequest()
req.recognitionLevel = .accurate
req.recognitionLanguages = ["zh-Hans", "en-US"]
try VNImageRequestHandler(cgImage: big, options: [:]).perform([req])
print("REGION \(x0),\(y0) \(w)x\(h) -> \(sw)x\(sh)")
for obs in (req.results ?? []) {
    guard let c = obs.topCandidates(1).first else { continue }
    let b = obs.boundingBox
    print(String(format: "  x=%4.0f y=%4.0f w=%4.0f h=%4.0f  %@",
                 Double(x0) + b.minX * Double(w), Double(y0) + (1 - b.maxY) * Double(h),
                 b.width * Double(w), b.height * Double(h), c.string))
}

