{"content": """"原型：递归 XY 切割（XY-cut）阅读顺序，对比现有 _reading_order 在 12 篇本机 PDF 上的结果。"""
import sys
sys.path.insert(0, "/Users/argszero/scm/github.com/argszero/papershelf/src")
import pymupdf
from papershelf.pipeline import parse as P

GAP = 2.0


def _split_all(blocks, axis):
    lo, hi = ((1, 3) if axis == "y" else (0, 2))
    ordered = sorted(blocks, key=lambda b: b["bbox"][lo])
    groups, cur, span = [], [], None
    for b in ordered:
        if cur and b["bbox"][lo] > span + GAP:
            groups.append(cur); cur = []; span = None
        cur.append(b)
        span = b["bbox"][hi] if span is None else max(span, b["bbox"][hi])
    groups.append(cur)
    return groups


def xy_order(blocks, depth=0):
    if len(blocks) <= 1:
        return list(blocks)
    if depth >= 8:
        return sorted(blocks, key=lambda b: (round(b["bbox"][1], 1), b["bbox"][0]))
    for axis in ("y", "x"):
        groups = _split_all(blocks, axis)
        if len(groups) > 1:
            out = []
            for g in groups:
                out.extend(xy_order(g, depth + 1))
            return out
    return sorted(blocks, key=lambda b: (round(b["bbox"][1], 1), b["bbox"][0]))


if __name__ == "__main__":
    pdf = sys.argv[1]
    d = pymupdf.open(pdf)
    for pno in range(min(2, d.page_count)):
        page = d[pno]
        blocks = [b for b in page.get_text("dict")["blocks"]
                  if b.get("type") == 0 and P._block_text(b)]
        print(f"===== page {pno+1} old =====")
        old = P._reading_order(blocks, page.rect.width, P._two_column(blocks, page.rect.width))
        for b in old[:12]:
            print(f"  {[round(v) for v in b['bbox']]} :: {P._block_text(b)[:60]}")
        print(f"===== page {pno+1} xy-cut =====")
        for b in xy_order(blocks)[:12]:
            print(f"  {[round(v) for v in b['bbox']]} :: {P._block_text(b)[:60]}")
