{"content": """"v2：先找「通高纵向空白（gutter）」切栏，切不动再横切。对比 v1（先横后纵）。"""
import sys, glob, os
sys.path.insert(0, "/Users/argszero/scm/github.com/argszero/papershelf/src")
import pymupdf
from papershelf.pipeline import parse as P

MIN_GUTTER = 6.0   # 纵向空白带最小宽度（pt）
MIN_BAND = 4.0     # 横向空白带最小高度（pt）
MAX_DEPTH = 12


def _gutters(blocks):
    """返回能把 blocks 切开的一串纵向空白带（按 x 排序，互不相邻）。"""
    lo = min(b["bbox"][0] for b in blocks)
    hi = max(b["bbox"][2] for b in blocks)
    y0 = min(b["bbox"][1] for b in blocks)
    y1 = max(b["bbox"][3] for b in blocks)
    ordered = sorted(blocks, key=lambda b: b["bbox"][0])
    cuts, end = [], None
    for b in ordered:
        if end is not None and b["bbox"][0] - end >= MIN_GUTTER:
            cuts.append((end, b["bbox"][0]))
        end = b["bbox"][2] if end is None else max(end, b["bbox"][2])
    # 只保留「通高」的带：带内没有任何块跨过（由上面的扫描已保证），
    # 且带必须真的在页面内部（两端都还有块）
    return cuts


def _hband(blocks):
    """返回能把 blocks 切开的横向空白带。"""
    ordered = sorted(blocks, key=lambda b: b["bbox"][1])
    cuts, end = [], None
    for b in ordered:
        if end is not None and b["bbox"][1] - end >= MIN_BAND:
            cuts.append((end, b["bbox"][1]))
        end = b["bbox"][3] if end is None else max(end, b["bbox"][3])
    return cuts


def v2(blocks, depth=0):
    if len(blocks) <= 1:
        return list(blocks)
    if depth < MAX_DEPTH:
        cuts = _gutters(blocks)
        if cuts:
            out = []
            for cut in cuts:
                pass
            # 按带切分
            groups, cur, end = [], [], None
            for b in sorted(blocks, key=lambda x: x["bbox"][0]):
                if end is not None and b["bbox"][0] - end >= MIN_GUTTER:
                    groups.append(cur); cur = []
                cur.append(b)
                end = b["bbox"][2] if end is None else max(end, b["bbox"][2])
            if cur:
                groups.append(cur)
            if len(groups) > 1:
                for g in groups:
                    out.extend(v2(g, depth + 1))
                return out
        bands = _hband(blocks)
        if bands:
            groups, cur, end = [], [], None
            for b in sorted(blocks, key=lambda x: x["bbox"][1]):
                if end is not None and b["bbox"][1] - end >= MIN_BAND:
                    groups.append(cur); cur = []
                cur.append(b)
                end = b["bbox"][3] if end is None else max(end, b["bbox"][3])
            if cur:
                groups.append(cur)
            if len(groups) > 1:
                out = []
                for g in groups:
                    out.extend(v2(g, depth + 1))
                return out
    return sorted(blocks, key=lambda b: (round(b["bbox"][1], 1), b["bbox"][0]))


def v1(blocks, depth=0):
    """先横后纵。"""
    if len(blocks) <= 1:
        return list(blocks)
    if depth < MAX_DEPTH:
        for axis, gap, lo, hi in (("y", MIN_BAND, 1, 3), ("x", MIN_GUTTER, 0, 2)):
            groups, cur, end = [], [], None
            for b in sorted(blocks, key=lambda x: x["bbox"][lo]):
                if end is not None and b["bbox"][lo] - end >= gap:
                    groups.append(cur); cur = []
                cur.append(b)
                end = b["bbox"][hi] if end is None else max(end, b["bbox"][hi])
            if cur:
                groups.append(cur)
            if len(groups) > 1:
                out = []
                for g in groups:
                    out.extend(v1(g, depth + 1))
                return out
    return sorted(blocks, key=lambda b: (round(b["bbox"][1], 1), b["bbox"][0]))


def alternation(seq, width):
    """两栏页里 L/R 交替次数 —— 越大越像"逐行交错"的乱序。"""
    mid = width / 2
    sides = ["L" if b["bbox"][0] < mid else "R" for b in seq]
    return sum(1 for a, b in zip(sides, sides[1:]) if a != b)


if __name__ == "__main__":
    BASE = "/Users/argszero/scm/github.com/argszero/pku-paper-3d/papers/外部文献/第一批"
    tot = {"old": 0, "v1": 0, "v2": 0}
    alt_bad = {"old": [], "v1": [], "v2": []}
    for pdf in sorted(glob.glob(os.path.join(BASE, "*", "original.pdf"))):
        name = os.path.basename(os.path.dirname(pdf))
        d = pymupdf.open(pdf)
        for pno in range(d.page_count):
            page = d[pno]
            blocks = [b for b in page.get_text("dict")["blocks"]
                      if b.get("type") == 0 and P._block_text(b)]
            if len(blocks) < 3:
                continue
            W = page.rect.width
            tc = P._two_column(blocks, W)
            # 只统计"整页都是双栏"（无通栏块）的页面，看是否交错
            spans = [b for b in blocks if b["bbox"][2] - b["bbox"][0] > W * 0.72]
            if not tc or spans:
                continue
            for label, fn in (("old", None), ("v1", v1), ("v2", v2)):
                seq = P._reading_order(blocks, W, True) if fn is None else fn(blocks)
                a = alternation(seq, W)
                tot[label] += 1
                if a > 3:
                    alt_bad[label].append((name, pno + 1, a))
    for k in tot:
        print(f"{k}: 双栏页 {tot[k]} 个，其中严重交错(>3 次) {len(alt_bad[k])} 个 {alt_bad[k][:6]}")
