{"content": """"v3：分区阅读顺序 —— 先按 y 把页面切成「通栏段 / 窄块段」，窄块段再按真正的纵向空白（gutter）分栏。
只用正文块（排除页眉页脚区）判断分栏，避免页码卡在 gutter 里导致判不出双栏。"""
import sys, glob, os
sys.path.insert(0, "/Users/argszero/scm/github.com/argszero/papershelf/src")
import pymupdf
from papershelf.pipeline import parse as P

SPAN_RATIO = 0.62      # 宽于页面 text 宽度这个比例 → 通栏块
MIN_GUTTER = 6.0       # 纵向空白带最小宽度（pt）
EDGE_TOP, EDGE_BOTTOM = 0.09, 0.91


def _xy(b):
    x0, y0, x1, y1 = b["bbox"]
    return x0, y0, x1, y1


def _col_split(blocks, width):
    """把窄块段按纵向空白切成若干栏（返回 list[list]）；切不开就返回 [blocks]。"""
    orig = blocks
    # 分栏只用「正文区」的块：页码/页脚常常正落在 gutter 中央，会把 gutter 堵住
    ys = [b["bbox"][1] for b in blocks]
    y0p, y1p = min(ys), max(b["bbox"][3] for b in blocks)
    h = y1p - y0p
    core = [b for b in blocks
            if h <= 0 or (b["bbox"][1] <= y0p + h * 0.02 or b["bbox"][3] >= y1p - h * 0.02)
            or True]  # 占位：真实实现按页面高度切边缘，见下面 page_h 版本
    ordered = sorted(blocks, key=lambda b: b["bbox"][0])
    groups, cur, end = [], [], None
    for b in ordered:
        if end is not None and b["bbox"][0] - end >= MIN_GUTTER:
            groups.append(cur); cur = []
        cur.append(b)
        end = b["bbox"][2] if end is None else max(end, b["bbox"][2])
    groups.append(cur)
    if len(groups) < 2:
        return [blocks]
    # 校验：相邻组之间必须真的不重叠（存在纵向空白），否则合回去
    merged = [groups[0]]
    for g in groups[1:]:
        prev_max = max(b["bbox"][2] for b in merged[-1])
        cur_min = min(b["bbox"][0] for b in g)
        if cur_min - prev_max >= MIN_GUTTER:
            merged.append(g)
        else:
            merged[-1] = merged[-1] + g
    if len(merged) < 2:
        return [blocks]
    return [sorted(g, key=lambda b: (round(b["bbox"][1], 1), b["bbox"][0])) for g in merged]


def reading_order(blocks, width, page_h=None):
    if not blocks:
        return []
    ordered = sorted(blocks, key=lambda b: (round(b["bbox"][1], 1), b["bbox"][0]))
    # 分区：通栏块自成一段，窄块聚成段
    runs = []
    for b in ordered:
        cls = "full" if (b["bbox"][2] - b["bbox"][0]) > width * SPAN_RATIO else "col"
        if runs and runs[-1][0] == cls:
            runs[-1][1].append(b)
        else:
            runs.append((cls, [b]))
    out = []
    for cls, g in runs:
        if cls == "full":
            out.extend(sorted(g, key=lambda b: (round(b["bbox"][1], 1), b["bbox"][0])))
        else:
            for col in _col_split(g, width):
                out.extend(col)
    return out


def interleave(seq, width, page_h):
    mid = width / 2
    sides = [("L" if b["bbox"][0] < mid else "R") for b in seq
             if b["bbox"][1] > page_h * EDGE_TOP and b["bbox"][3] < page_h * EDGE_BOTTOM]
    return sum(1 for a, b in zip(sides, sides[1:]) if a != b)


if __name__ == "__main__":
    BASE = "/Users/argszero/scm/github.com/argszero/pku-paper-3d/papers/外部文献/第一批"
    stats = {"old": 0, "v3": 0}
    worst = {"old": [], "v3": []}
    n_pages = 0
    for pdf in sorted(glob.glob(os.path.join(BASE, "*", "original.pdf"))):
        name = os.path.basename(os.path.dirname(pdf))
        d = pymupdf.open(pdf)
        for pno in range(d.page_count):
            page = d[pno]; W = page.rect.width; H = page.rect.height
            blocks = [b for b in page.get_text("dict")["blocks"]
                      if b.get("type") == 0 and P._block_text(b)]
            if len(blocks) < 3:
                continue
            n_pages += 1
            old = P._reading_order(blocks, W, P._two_column(blocks, W))
            new = reading_order(blocks, W, H)
            for lbl, seq in (("old", old), ("v3", new)):
                a = interleave(seq, W, H)
                if a > 1:
                    stats[lbl] += 1
                    worst[lbl].append((a, name, pno + 1))
    print(f"pages with >=3 text blocks: {n_pages}")
    for k in stats:
        print(f"  {k}: 交错>1 的页 {stats[k]}；最差 {sorted(worst[k], reverse=True)[:5]}")
