{"content": """"v4：分区阅读顺序 + **只用正文带找纵向空白(gutter)**。

v3 的病灶：页码常常正落在两栏之间的空白里（如 "186" 在 x=292..305），
按全页块找 gutter 会被它"桥接"，判不出双栏 → 回落成逐行交错。
所以找 gutter 时必须**排除页边带**（页眉/页脚/页码）。
"""
import sys, glob, os
sys.path.insert(0, "/Users/argszero/scm/github.com/argszero/papershelf/src")
import pymupdf
from papershelf.pipeline import parse as P

SPAN_RATIO = 0.62      # 宽于 text 宽度这个比例 → 通栏（跨栏）块
MIN_GUTTER = 6.0       # 纵向空白带最小宽度（pt）
EDGE_TOP, EDGE_BOTTOM = 0.09, 0.91


def _split_by_x(blocks):
    """按纵向空白切成若干组（相邻组之间必须有 >= MIN_GUTTER 的空白）。"""
    groups, cur, end = [], [], None
    for b in sorted(blocks, key=lambda b: b["bbox"][0]):
        if end is not None and b["bbox"][0] - end >= MIN_GUTTER:
            groups.append(cur); cur = []
        cur.append(b)
        end = b["bbox"][2] if end is None else max(end, b["bbox"][2])
    if cur:
        groups.append(cur)
    return groups


def _columns(blocks, page_h):
    """把 blocks 按列切开；切不开返回 None。

    找 gutter 只用**正文带**里的块（排除页眉/页脚/页码），否则页码会把 gutter 堵住。
    """
    body = [b for b in blocks
            if b["bbox"][3] > page_h * EDGE_TOP and b["bbox"][1] < page_h * EDGE_BOTTOM]
    if len(body) < 2:
        return None
    groups = _split_by_x(body)
    if len(groups) < 2:
        return None
    # 用正文带定出的「栏边界」去切全部块：按每栏的 x 范围判定块属于哪一栏
    bounds = [(min(b["bbox"][0] for b in g), max(b["bbox"][2] for b in g)) for g in groups]
    cols = [[] for _ in bounds]
    for b in blocks:
        cx = (b["bbox"][0] + b["bbox"][2]) / 2
        best, bestd = 0, None
        for i, (x0, x1) in enumerate(bounds):
            d = 0.0 if x0 <= cx <= x1 else min(abs(cx - x0), abs(cx - x1))
            if bestd is None or d < bestd:
                best, bestd = i, d
        cols[best].append(b)
    if any(not c for c in cols):
        return None
    return [sorted(c, key=lambda b: (round(b["bbox"][1], 1), b["bbox"][0])) for c in cols]


def reading_order(blocks, width, page_h):
    if not blocks:
        return []
    ordered = sorted(blocks, key=lambda b: (round(b["bbox"][1], 1), b["bbox"][0]))
    # 分区：通栏块自成一段，窄块聚成段（窄块段内再分栏）
    runs = []
    for b in ordered:
        cls = "full" if (b["bbox"][2] - b["bbox"][0]) > width * SPAN_RATIO else "col"
        if runs and runs[-1][0] == cls:
            runs[-1][1].append(b)
        else:
            runs.append((cls, [b]))
    out = []
    for cls, g in runs:
        if cls == "full":
            out.extend(sorted(g, key=lambda b: (round(b["bbox"][1], 1), b["bbox"][0])))
